def _elapsed_clock(seconds):
    seconds=max(0,int(seconds or 0))
    hours,rem=divmod(seconds,3600)
    minutes,seconds=divmod(rem,60)
    return f"{hours}:{minutes:02d}:{seconds:02d}" if hours else f"{minutes}:{seconds:02d}"
